package com.example;

// Minimal mock for org.eclipse.jdt.core.IJavaElement
interface IJavaElement {
    String getElementName(); 
}

// Minimal mock for org.eclipse.jdt.internal.ui.util.ActionUtil
class ActionUtil {
    public static boolean isOnBuildPath(IJavaElement element) {
        // Simulate behavior that would throw NPE if element is null
        return element.getElementName() != null; 
    }
}

public class TestClass {
    public void processElement(IJavaElement input) {
        // This line is problematic if 'input' is null and ActionUtil.isOnBuildPath
        // does not handle nulls (which it implicitly doesn't in the original code)
        if (ActionUtil.isOnBuildPath(input)) {
            System.out.println("Input is on build path.");
        }
    }

    public static void main(String[] args) {
        TestClass tc = new TestClass();
        // This call is intended to trigger an NPE before the fix
        tc.processElement(null);
    }
}

